const $=id=>document.getElementById(id);
let currentSession=null,toastTimer;
const pageNames={chat:"Chat",models:"Models & providers",orchestration:"AI orchestration",memory:"Topic memory",sessions:"Sessions",usage:"Usage & analytics",settings:"Settings"};
async function api(url,opts={}){const r=await fetch(url,{...opts,headers:{"Content-Type":"application/json",...(opts.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||"Request failed");return d}
function toast(msg){const t=$("toast");t.textContent=msg;t.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove("show"),2800)}
function showLogin(){$("login-screen").classList.remove("hidden");$("app").classList.add("hidden")}
function showApp(){$("login-screen").classList.add("hidden");$("app").classList.remove("hidden")}
async function checkAuth(){try{const s=await api("/api/status");showApp();updateProvider(s.gemini_configured);await loadSessions();if(!s.gemini_configured){$("setup-banner").classList.remove("hidden");showSetupNudge()}}catch{showLogin()}}
function updateProvider(connected){$("header-provider-state").textContent=connected?"CONNECTED":"SETUP";$("header-provider-state").classList.toggle("connected",connected);$("models-gemini-status").textContent=connected?"CONNECTED":"NEEDS SETUP";$("models-gemini-status").classList.toggle("connected",connected);$("settings-provider-state").textContent=connected?"Connected":"Not connected";$("settings-provider-state").classList.toggle("connected",connected)}
function showSetupNudge(){if(!currentSession)$("chat-empty").classList.remove("hidden")}
$("login-form").addEventListener("submit",async e=>{e.preventDefault();$("login-error").textContent="";try{await api("/api/login",{method:"POST",body:JSON.stringify({username:$("username").value,password:$("password").value})});await checkAuth()}catch(err){$("login-error").textContent=err.message}});
$("logout").onclick=async()=>{try{await api("/api/logout",{method:"POST"})}finally{showLogin()}};
async function loadSessions(){const sessions=await api("/api/sessions");$("session-list").innerHTML="";$("sessions-grid").innerHTML="";$("chat-count").textContent=String(sessions.length).padStart(2,"0");sessions.forEach(s=>{const b=document.createElement("button");b.className="session-item"+(s.id===currentSession?" active":"");b.textContent=s.title;b.onclick=()=>openSession(s.id);$("session-list").appendChild(b);const card=document.createElement("button");card.className="session-card";const title=document.createElement("b");title.textContent=s.title;const meta=document.createElement("span");meta.textContent="Open conversation →";card.append(title,meta);card.onclick=()=>{switchPage("chat");openSession(s.id)};$("sessions-grid").appendChild(card)});if(!currentSession&&sessions.length)await openSession(sessions[0].id,false)}
async function newSession(){const s=await api("/api/sessions",{method:"POST"});currentSession=s.id;$("chat-empty").classList.add("hidden");$("chat-active").classList.remove("hidden");$("conversation-title").textContent="New conversation";$("messages").innerHTML="";await loadSessions();$("message-input").focus()}
async function openSession(id,refresh=true){currentSession=id;const msgs=await api("/api/messages?session_id="+encodeURIComponent(id));$("chat-empty").classList.add("hidden");$("chat-active").classList.remove("hidden");$("messages").innerHTML="";msgs.forEach(addMessage);const sessionBtn=[...$("session-list").children].find(x=>x.classList.contains("active"));$("conversation-title").textContent=sessionBtn?.textContent||"Conversation";if(refresh)await loadSessions();$("messages").scrollTop=$("messages").scrollHeight}
function addMessage(m){const row=document.createElement("div");row.className="message "+m.role;const av=document.createElement("div");av.className="message-avatar";av.textContent=m.role==="user"?"S":"✳";const bubble=document.createElement("div");bubble.className="bubble";bubble.textContent=m.content;row.append(av,bubble);$("messages").appendChild(row)}
$("new-chat").onclick=$("hero-start").onclick=$("clear-view").onclick=$("sessions-new").onclick=()=>newSession();
$("refresh-sessions").onclick=()=>loadSessions();
$("chat-form").addEventListener("submit",async e=>{e.preventDefault();const input=$("message-input"),message=input.value.trim();if(!message)return;if(!currentSession)await newSession();input.value="";addMessage({role:"user",content:message});addMessage({role:"assistant",content:"Thinking…"});const send=$("chat-form").querySelector(".send-button");send.disabled=true;try{const out=await api("/api/messages",{method:"POST",body:JSON.stringify({session_id:currentSession,message,model:$("model").value})});$("messages").lastElementChild.remove();addMessage({role:"assistant",content:out.reply});toast(`Response received · ${out.latency_ms} ms`)}catch(err){$("messages").lastElementChild.remove();addMessage({role:"assistant",content:"Unable to complete request: "+err.message})}finally{send.disabled=false;await loadSessions();$("messages").scrollTop=$("messages").scrollHeight}});
$("message-input").addEventListener("keydown",e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();$("chat-form").requestSubmit()}});
function switchPage(name){document.querySelectorAll(".page").forEach(p=>p.classList.add("hidden"));$("page-"+name).classList.remove("hidden");document.querySelectorAll(".nav-link").forEach(b=>b.classList.toggle("active",b.dataset.page===name));$("breadcrumb-page").textContent=pageNames[name];$("sidebar").classList.remove("open");if(name==="sessions")loadSessions();if(name==="settings")refreshStatus()}
document.querySelectorAll(".nav-link").forEach(b=>b.addEventListener("click",()=>switchPage(b.dataset.page)));
document.querySelectorAll("[data-goto]").forEach(b=>b.addEventListener("click",()=>switchPage(b.dataset.goto)));
$("setup-open").onclick=()=>switchPage("settings");
$("add-provider").onclick=()=>{switchPage("settings");toast("More providers will be added in a future release.")};
async function refreshStatus(){try{const s=await api("/api/status");updateProvider(s.gemini_configured);if(s.gemini_configured)$("setup-banner").classList.add("hidden")}catch{}}
$("api-key-form").addEventListener("submit",async e=>{e.preventDefault();const key=$("api-key").value.trim();if(!key){$("key-feedback").textContent="Enter your API key first.";return}const btn=e.submitter;btn.disabled=true;btn.textContent="Saving…";try{await api("/api/setup/gemini",{method:"POST",body:JSON.stringify({api_key:key})});$("api-key").value="";$("key-feedback").textContent="Gemini API key saved securely on this server.";updateProvider(true);$("setup-banner").classList.add("hidden");toast("Gemini is connected. Start a conversation.");switchPage("chat")}catch(err){$("key-feedback").textContent=err.message}finally{btn.disabled=false;btn.innerHTML='Save API key <span>↗</span>'}});
$("toggle-key").onclick=()=>{const i=$("api-key");i.type=i.type==="password"?"text":"password";$("toggle-key").textContent=i.type==="password"?"Show":"Hide"};
document.querySelectorAll(".settings-tab").forEach(b=>b.onclick=()=>{document.querySelectorAll(".settings-tab").forEach(x=>x.classList.toggle("active",x===b));document.querySelectorAll(".settings-panel").forEach(x=>x.classList.add("hidden"));$(b.dataset.tab).classList.remove("hidden")});
$("mobile-menu").onclick=()=>$("sidebar").classList.add("open");$("mobile-close").onclick=()=>$("sidebar").classList.remove("open");
document.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();newSession()}if(e.key==="Escape")$("sidebar").classList.remove("open")});
checkAuth();
